#!/usr/bin/env bash
# Probe for VSC-348: the zero-findings README badge must not present a stale ledger.
# Runs the compute_badges.sh OF THE TREE UNDER TEST (cwd) against a throwaway shared
# clone of that tree in $TMPDIR. (a) planted: a ledger with a row removed -> the badge
# must say the ledger is stale; (b) control: the ledger regenerated by the sweep -> the
# badge must NOT say stale. Exit: 0 holds, 1 violated, 2 cannot determine.
set -u
cb="$PWD/scripts/badges/compute_badges.sh"
[ -f "$cb" ] || { echo "probe: compute_badges.sh missing"; exit 2; }
t=$(mktemp -d) || exit 2
trap 'rm -rf "$t"' EXIT
git clone -q --shared "$PWD" "$t/r" 2>/dev/null || { echo "probe: clone failed"; exit 2; }
r="$t/r"; led="$r/docs/findings/zero_findings_ledger.jsonl"
[ -f "$led" ] && [ -f "$r/scripts/audit/zero_findings_sweep.sh" ] || { echo "probe: ledger or sweep absent in clone"; exit 2; }
badge() { timeout 150 bash "$cb" --root "$r" 2>/dev/null | grep -o 'zero%20findings-[^)]*' | head -1; }
# control: fresh ledger from the live sweep (rc ignored: a ratchet refusal still writes nothing wrong)
bash "$r/scripts/audit/zero_findings_sweep.sh" --write-ledger --root "$r" >/dev/null 2>&1
[ -s "$led" ] || { echo "probe: could not regenerate the control ledger"; exit 2; }
c=$(badge); echo "control badge: $c"
[ -n "$c" ] || exit 2
case "$c" in *stale*|*unverified*) echo "probe: control (fresh ledger) was flagged"; exit 2 ;; esac
# planted: drop a row so the ledger is stale
head -n -1 "$led" > "$led.new" && mv "$led.new" "$led"
p=$(badge); echo "planted-stale badge: $p"
case "$p" in *stale*|*unverified*) exit 0 ;; *) echo "stale ledger presented as a count"; exit 1 ;; esac
